alter table public.messages add column co_sender_name text, add column co_sender_role text, add column co_sender_branch text;
create or replace function public._co_sender_snapshot() returns trigger language plpgsql set search_path=public as $$ declare o uuid; begin select org_id into o from conversations where id=new.conversation_id and dedupe_key='co:'||org_id::text; if o is not null then if not _co_ok(o) then raise exception 'غير مصرح للمجتمع'; end if; select p.full_name,c.role,coalesce(s.name,'إدارة المجموعة') into new.co_sender_name,new.co_sender_role,new.co_sender_branch from user_active_context c join profiles p on p.id=c.user_id left join schools s on s.id=c.school_id where c.user_id=auth.uid() and c.org_id=o; end if; return new; end $$;
create trigger co_sender_snapshot before insert on public.messages for each row execute function public._co_sender_snapshot();
create or replace function public.co_sender_labels(_conv uuid) returns table(message_id uuid,name text,role text,branch text) language sql stable security invoker set search_path=public as $$ select m.id,m.co_sender_name,m.co_sender_role,m.co_sender_branch from messages m join conversations c on c.id=m.conversation_id where c.id=_conv and c.dedupe_key='co:'||c.org_id::text and _co_ok(c.org_id) and can_read_conv_at(c.id,m.created_at) $$;
revoke all on function public.co_sender_labels(uuid) from public,anon; grant execute on function public.co_sender_labels(uuid) to authenticated,service_role;
create or replace function public._org_academic_guard() returns trigger language plpgsql set search_path=public as $$ begin if not is_org_owner(new.org_id) then raise exception 'غير مصرح'; end if; if tg_op='UPDATE' and (new.id,new.org_id,new.kind) is distinct from (old.id,old.org_id,old.kind) then raise exception 'نوع ونطاق المحدد ثابتان'; end if; new.name:=trim(new.name); if new.kind not in ('year','term','stage','grade') or length(new.name)<1 or length(new.name)>100 then raise exception 'محدد غير صالح'; end if; if new.kind='grade' then if not exists(select 1 from academic_catalog where kind='stage' and name=new.stage) and not exists(select 1 from org_academic_catalog where org_id=new.org_id and kind='stage' and name=new.stage) then raise exception 'المرحلة غير معتمدة'; end if; else new.stage:=null; end if; if exists(select 1 from org_academic_catalog c where c.org_id=new.org_id and c.kind=new.kind and c.name=new.name and c.stage is not distinct from new.stage and c.id<>new.id) then raise exception 'المحدد موجود بالفعل'; end if; return new; end $$;
create trigger org_academic_guard before insert or update on public.org_academic_catalog for each row execute function public._org_academic_guard();
create or replace function public._academic_grade_guard() returns trigger language plpgsql set search_path=public as $$ declare st text; begin select name into st from stages where id=new.stage_id and school_id=new.school_id; if st is null then raise exception 'المرحلة ليست في الفرع'; end if; if tg_op='INSERT' or (new.name,new.stage_id) is distinct from (old.name,old.stage_id) then if not exists(select 1 from academic_catalog where kind='grade' and name=new.name and stage=st) and not exists(select 1 from org_academic_catalog where org_id=school_org(new.school_id) and kind='grade' and name=new.name and stage=st) then raise exception 'الصف غير معتمد لهذه المرحلة'; end if; end if; return new; end $$;
create trigger academic_grade_validation before insert or update on public.grades for each row execute function public._academic_grade_guard();